describe('User Login with Valid Credentials', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should successfully log in with valid credentials and redirect to dashboard', () => {
    cy.intercept('POST', '/api/auth/login').as('loginRequest');

    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="email-input"]').type('user@example.com');

    cy.get('[data-testid="password-input"]').should('be.visible');
    cy.get('[data-testid="password-input"]').type('ValidPassword123!');

    cy.get('[data-testid="login-button"]').should('be.visible');
    cy.get('[data-testid="login-button"]').click();

    cy.wait('@loginRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="welcome-message"]').should('be.visible');
    cy.get('[data-testid="welcome-message"]').should('contain', 'Welcome back');

    cy.get('[data-testid="user-profile-icon"]').should('be.visible');
    cy.get('[data-testid="logout-button"]').should('be.visible');
  });

  it('should display error message when login fails with invalid credentials', () => {
    cy.intercept('POST', '/api/auth/login', {
      statusCode: 401,
      body: { error: 'Invalid email or password' }
    }).as('failedLoginRequest');

    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('WrongPassword123!');

    cy.get('[data-testid="login-button"]').click();

    cy.wait('@failedLoginRequest');

    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid email or password');

    cy.url().should('include', '/login');
    cy.get('[data-testid="welcome-message"]').should('not.exist');

    cy.get('[data-testid="email-input"]').should('have.value', 'user@example.com');
    cy.get('[data-testid="password-input"]').should('have.value', 'WrongPassword123!');
  });
});

describe('Authentication - Incorrect Password Error Message', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should display error message when user enters incorrect password', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginAttempt');

    // Fill in valid email
    cy.get('[data-testid="email-input"]').type('user@example.com');

    // Fill in incorrect password
    cy.get('[data-testid="password-input"]').type('wrongpassword123');

    // Click login button
    cy.get('[data-testid="login-button"]').click();

    // Wait for API response
    cy.wait('@loginAttempt');

    // Assert error message is visible
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Invalid password');

    // Assert error message has correct styling (red color indicator)
    cy.get('[data-testid="error-message"]')
      .should('have.css', 'color')
      .and('include', 'rgb(220, 53, 69)');

    // Assert password field is still visible for retry
    cy.get('[data-testid="password-input"]').should('be.visible');

    // Assert login button is still enabled
    cy.get('[data-testid="login-button"]').should('not.be.disabled');
  });

  it('should display error message and handle edge case with empty password field', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginAttempt');

    // Fill in valid email
    cy.get('[data-testid="email-input"]').type('user@example.com');

    // Leave password empty and click login
    cy.get('[data-testid="login-button"]').click();

    // Wait for API response or validation
    cy.wait('@loginAttempt');

    // Assert appropriate error message is displayed
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Password is required');

    // Assert error state is applied to password field
    cy.get('[data-testid="password-input"]')
      .should('have.class', 'is-invalid');

    // Verify user can correct and retry
    cy.get('[data-testid="password-input"]').type('correctpassword');
    cy.get('[data-testid="password-input"]').should('not.have.class', 'is-invalid');
  });
});

describe('User Logout - Secure Session Termination', () => {
  beforeEach(() => {
    cy.visit('/login');
    cy.get('[data-testid="email-input"]').type('testuser@example.com');
    cy.get('[data-testid="password-input"]').type('ValidPassword123');
    cy.get('[data-testid="login-button"]').click();
    cy.intercept('POST', '/api/auth/login').as('loginRequest');
    cy.wait('@loginRequest');
    cy.get('[data-testid="dashboard-heading"]').should('be.visible');
  });

  it('should successfully log out user and clear session', () => {
    cy.intercept('POST', '/api/auth/logout').as('logoutRequest');
    cy.get('[data-testid="user-menu-button"]').click();
    cy.get('[data-testid="logout-link"]').should('be.visible').click();
    cy.wait('@logoutRequest');
    cy.get('[data-testid="login-form"]').should('be.visible');
    cy.url().should('include', '/login');
    cy.window().then((win) => {
      expect(win.sessionStorage.getItem('authToken')).to.be.null;
    });
  });

  it('should handle logout failure and display error message', () => {
    cy.intercept('POST', '/api/auth/logout', {
      statusCode: 500,
      body: { error: 'Server error during logout' }
    }).as('logoutFailure');
    cy.get('[data-testid="user-menu-button"]').click();
    cy.get('[data-testid="logout-link"]').click();
    cy.wait('@logoutFailure');
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Unable to log out');
    cy.get('[data-testid="dashboard-heading"]').should('be.visible');
    cy.url().should('include', '/dashboard');
  });
});

describe('Authentication - Protected Page Redirect', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should redirect unauthenticated user to login when accessing protected page', () => {
    // Clear all cookies and local storage to ensure unauthenticated state
    cy.clearCookies();
    cy.clearLocalStorage();

    // Attempt to visit protected dashboard page
    cy.visit('/dashboard', { failOnStatusCode: false });

    // Verify redirect to login page occurred
    cy.url().should('include', '/login');

    // Verify login form is visible
    cy.get('[data-testid="login-form"]').should('be.visible');

    // Verify login button exists and is enabled
    cy.get('[data-testid="login-button"]').should('be.visible').and('not.be.disabled');

    // Verify email input field is present
    cy.get('[data-testid="email-input"]').should('be.visible');

    // Verify password input field is present
    cy.get('[data-testid="password-input"]').should('be.visible');
  });

  it('should handle rapid redirect attempts and prevent infinite loops', () => {
    // Clear authentication state
    cy.clearCookies();
    cy.clearLocalStorage();

    // Setup API intercept for login page request
    cy.intercept('GET', '/api/auth/verify').as('verifyAuth');

    // Attempt to access protected resource multiple times
    cy.visit('/dashboard', { failOnStatusCode: false });
    cy.wait('@verifyAuth');

    // Verify we're on login page after first attempt
    cy.url().should('include', '/login');

    // Try accessing another protected page
    cy.visit('/profile', { failOnStatusCode: false });

    // Should still be on login, not in redirect loop
    cy.url().should('include', '/login');

    // Verify no error messages are shown
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Verify login form is still functional
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="password-input"]').should('be.visible');

    // Attempt to fill login form to verify it's still interactive
    cy.get('[data-testid="email-input"]').type('test@example.com');
    cy.get('[data-testid="password-input"]').type('password123');

    // Verify form submission button is available
    cy.get('[data-testid="login-button"]').should('be.visible').and('not.be.disabled');
  });
});

describe('Password Reset Confirmation Message', () => {
  beforeEach(() => {
    cy.visit('/forgot-password');
  });

  it('should display confirmation message after successful password reset', () => {
    // Intercept the password reset API call
    cy.intercept('POST', '/api/auth/reset-password').as('resetPassword');

    // Fill in the email field
    cy.get('[data-testid="email-input"]').type('user@example.com');

    // Click the reset password button
    cy.get('[data-testid="reset-button"]').click();

    // Wait for the API call and mock successful response
    cy.wait('@resetPassword').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify confirmation message is visible
    cy.get('[data-testid="confirmation-message"]')
      .should('be.visible')
      .should('contain', 'Password reset successful');

    // Verify the message has the correct styling/type
    cy.get('[data-testid="confirmation-message"]')
      .should('have.class', 'success-alert');

    // Verify redirect link is visible
    cy.get('[data-testid="login-redirect-link"]')
      .should('be.visible')
      .should('contain', 'Return to Login');
  });

  it('should not display confirmation message when reset fails', () => {
    // Intercept the password reset API call with error response
    cy.intercept('POST', '/api/auth/reset-password', {
      statusCode: 400,
      body: { error: 'Invalid email address' }
    }).as('resetPasswordError');

    // Fill in invalid email
    cy.get('[data-testid="email-input"]').type('invalid-email');

    // Click the reset password button
    cy.get('[data-testid="reset-button"]').click();

    // Wait for the failed API call
    cy.wait('@resetPasswordError');

    // Verify success confirmation message does NOT appear
    cy.get('[data-testid="confirmation-message"]').should('not.exist');

    // Verify error message is displayed instead
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Invalid email address');

    // Verify user is still on the reset page
    cy.url().should('include', '/forgot-password');
  });
});

describe('Login Form Empty Field Validation', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should prevent form submission when email and password fields are empty', () => {
    // Attempt to submit the form without entering any data
    cy.get('[data-testid="login-submit-btn"]').click();

    // Verify error messages appear for both fields
    cy.get('[data-testid="email-error-message"]')
      .should('be.visible')
      .should('contain', 'Email is required');

    cy.get('[data-testid="password-error-message"]')
      .should('be.visible')
      .should('contain', 'Password is required');

    // Verify the form was not submitted (no redirect or API call)
    cy.url().should('include', '/login');
    cy.get('[data-testid="login-form"]').should('be.visible');
  });

  it('should prevent form submission when only email field is filled and password is empty', () => {
    // Fill only the email field
    cy.get('[data-testid="email-input"]')
      .type('user@example.com');

    // Attempt to submit the form
    cy.get('[data-testid="login-submit-btn"]').click();

    // Verify error message appears only for password field
    cy.get('[data-testid="password-error-message"]')
      .should('be.visible')
      .should('contain', 'Password is required');

    // Verify error message does NOT appear for email field
    cy.get('[data-testid="email-error-message"]')
      .should('not.exist');

    // Verify the form was not submitted
    cy.url().should('include', '/login');
    cy.get('[data-testid="login-form"]').should('be.visible');
  });
});

describe('Remember Me Checkbox - Authentication', () => {
  beforeEach(() => {
    cy.visit('/login');
    cy.clearLocalStorage();
    cy.clearCookies();
  });

  it('should persist user session when Remember Me is checked', () => {
    // Fill login form
    cy.get('[data-testid="email-input"]').type('testuser@example.com');
    cy.get('[data-testid="password-input"]').type('securePassword123');

    // Check Remember Me checkbox
    cy.get('[data-testid="remember-me-checkbox"]').click();
    cy.get('[data-testid="remember-me-checkbox"]').should('be.checked');

    // Submit login form
    cy.get('[data-testid="login-button"]').click();

    // Intercept and wait for session API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');
    cy.wait('@loginRequest').then((interception) => {
      expect(interception.request.body).to.include('rememberMe: true');
    });

    // Verify redirect to dashboard
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="welcome-message"]').should('be.visible');

    // Verify session token is stored
    cy.window().then((win) => {
      const sessionToken = win.localStorage.getItem('sessionToken');
      expect(sessionToken).to.exist;
    });

    // Close browser tab and revisit (simulate new session)
    cy.visit('/dashboard');
    cy.get('[data-testid="user-profile-menu"]').should('be.visible');
    cy.get('[data-testid="logout-button"]').should('be.visible');
  });

  it('should not persist session when Remember Me is unchecked', () => {
    // Fill login form without checking Remember Me
    cy.get('[data-testid="email-input"]').type('testuser@example.com');
    cy.get('[data-testid="password-input"]').type('securePassword123');

    // Verify Remember Me checkbox is unchecked by default
    cy.get('[data-testid="remember-me-checkbox"]').should('not.be.checked');

    // Submit login form
    cy.intercept('POST', '/api/auth/login').as('loginRequest');
    cy.get('[data-testid="login-button"]').click();
    cy.wait('@loginRequest').then((interception) => {
      expect(interception.request.body).to.not.include('rememberMe: true');
    });

    // Verify successful login
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="welcome-message"]').should('contain', 'Welcome');

    // Clear session storage to simulate browser close
    cy.clearLocalStorage();
    cy.clearCookies();

    // Attempt to visit dashboard without session
    cy.visit('/dashboard');

    // Should be redirected to login
    cy.url().should('include', '/login');
    cy.get('[data-testid="session-expired-message"]').should('be.visible');
  });
});

describe('Login Loading Spinner', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should display loading spinner while login request is processing', () => {
    cy.intercept('POST', '/api/auth/login', (req) => {
      req.reply((res) => {
        res.delay(2000);
        res.send({
          statusCode: 200,
          body: { token: 'abc123', userId: 'user1' },
        });
      });
    }).as('loginRequest');

    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('password123');
    cy.get('[data-testid="login-button"]').click();

    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.get('[data-testid="spinner-text"]').should('contain', 'Logging in...');

    cy.wait('@loginRequest');

    cy.get('[data-testid="loading-spinner"]').should('not.exist');
    cy.url().should('include', '/dashboard');
  });

  it('should hide spinner and display error message on failed login request', () => {
    cy.intercept('POST', '/api/auth/login', {
      statusCode: 401,
      body: { error: 'Invalid credentials' },
    }).as('failedLogin');

    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('wrongpassword');
    cy.get('[data-testid="login-button"]').click();

    cy.get('[data-testid="loading-spinner"]').should('be.visible');

    cy.wait('@failedLogin');

    cy.get('[data-testid="loading-spinner"]').should('not.exist');
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid credentials');
    cy.url().should('include', '/login');
  });
});

describe('Account Lockout After 5 Failed Login Attempts', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should lock account after 5 consecutive failed login attempts', () => {
    const testEmail = 'testuser@example.com';
    const wrongPassword = 'wrongpassword123';

    // Attempt 1
    cy.get('[data-testid="email-input"]').type(testEmail);
    cy.get('[data-testid="password-input"]').type(wrongPassword);
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid credentials');

    // Attempt 2
    cy.get('[data-testid="password-input"]').clear().type(wrongPassword);
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid credentials');

    // Attempt 3
    cy.get('[data-testid="password-input"]').clear().type(wrongPassword);
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid credentials');

    // Attempt 4
    cy.get('[data-testid="password-input"]').clear().type(wrongPassword);
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid credentials');

    // Attempt 5 - Should trigger account lockout
    cy.get('[data-testid="password-input"]').clear().type(wrongPassword);
    cy.intercept('POST', '/api/auth/login').as('fifthLoginAttempt');
    cy.get('[data-testid="login-button"]').click();
    cy.wait('@fifthLoginAttempt');
    cy.get('[data-testid="lockout-message"]').should('be.visible');
    cy.get('[data-testid="lockout-message"]').should('contain', 'Account locked');
    cy.get('[data-testid="login-button"]').should('be.disabled');
  });

  it('should prevent login with correct credentials when account is locked', () => {
    const testEmail = 'lockeduser@example.com';
    const correctPassword = 'correctpassword123';

    // Pre-condition: Account is already locked
    cy.intercept('POST', '/api/auth/login', {
      statusCode: 423,
      body: { error: 'Account is locked due to multiple failed login attempts' }
    }).as('loginWithLockedAccount');

    cy.get('[data-testid="email-input"]').type(testEmail);
    cy.get('[data-testid="password-input"]').type(correctPassword);
    cy.get('[data-testid="login-button"]').click();
    cy.wait('@loginWithLockedAccount');

    cy.get('[data-testid="account-locked-banner"]').should('be.visible');
    cy.get('[data-testid="account-locked-banner"]').should('contain', 'locked');
    cy.get('[data-testid="unlock-instructions"]').should('contain', 'contact support');
    cy.get('[data-testid="login-button"]').should('be.disabled');
  });
});

describe('Google OAuth Login', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should successfully log in with valid Google OAuth credentials', () => {
    // Mock the Google OAuth window and API responses
    cy.intercept('POST', '/api/auth/google/callback', {
      statusCode: 200,
      body: {
        success: true,
        token: 'mock_jwt_token_12345',
        user: {
          id: 'user_123',
          email: 'testuser@gmail.com',
          name: 'Test User',
          picture: 'https://example.com/picture.jpg'
        }
      }
    }).as('googleAuth');

    cy.intercept('GET', '/api/user/profile', {
      statusCode: 200,
      body: {
        id: 'user_123',
        email: 'testuser@gmail.com',
        name: 'Test User',
        authenticated: true
      }
    }).as('userProfile');

    // Click Google Login button
    cy.get('[data-testid="google-login-btn"]').click();

    // Simulate Google OAuth popup window behavior
    cy.window().then((win) => {
      cy.stub(win, 'open').returns(win);
      cy.get('[data-testid="google-login-btn"]').click();
    });

    // Wait for OAuth callback
    cy.wait('@googleAuth');

    // Verify user is redirected to dashboard
    cy.url().should('include', '/dashboard');

    // Verify user profile is displayed
    cy.get('[data-testid="user-greeting"]').should('contain', 'Test User');
    cy.get('[data-testid="user-email"]').should('contain', 'testuser@gmail.com');

    // Verify authentication token is stored
    cy.window().then((win) => {
      expect(win.localStorage.getItem('auth_token')).to.equal('mock_jwt_token_12345');
    });

    // Verify logout button is available
    cy.get('[data-testid="logout-btn"]').should('be.visible');

    // Verify user profile API was called
    cy.wait('@userProfile');
  });

  it('should handle Google OAuth cancellation and network errors gracefully', () => {
    // Mock failed OAuth response
    cy.intercept('POST', '/api/auth/google/callback', {
      statusCode: 401,
      body: {
        success: false,
        error: 'oauth_cancelled',
        message: 'User cancelled Google OAuth flow'
      }
    }).as('googleAuthFailed');

    // Attempt to click Google Login button
    cy.get('[data-testid="google-login-btn"]').should('be.visible').click();

    // Wait for failed authentication
    cy.wait('@googleAuthFailed');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Authentication failed');

    // Verify user remains on login page
    cy.url().should('include', '/login');

    // Verify no authentication token is stored
    cy.window().then((win) => {
      expect(win.localStorage.getItem('auth_token')).to.be.null;
    });

    // Verify retry option is available
    cy.get('[data-testid="google-login-btn"]').should('be.visible');

    // Test network timeout scenario
    cy.intercept('POST', '/api/auth/google/callback', {
      delay: 30000,
      statusCode: 504
    }).as('googleAuthTimeout');

    cy.get('[data-testid="google-login-btn"]').click();

    // Verify timeout error handling
    cy.get('[data-testid="error-message"]', { timeout: 15000 }).should('contain', 'Connection timeout');
  });
});

describe('Password Strength Indicator', () => {
  beforeEach(() => {
    cy.visit('/auth/set-password');
  });

  it('should display password strength indicator and update as user types', () => {
    // Get password input field
    cy.get('[data-testid="password-input"]').should('be.visible');

    // Initially, strength indicator should not be visible or show empty state
    cy.get('[data-testid="strength-indicator"]').should('not.exist');

    // Type a weak password
    cy.get('[data-testid="password-input"]').type('abc');
    cy.get('[data-testid="strength-indicator"]').should('be.visible');
    cy.get('[data-testid="strength-level"]').should('contain', 'Weak');
    cy.get('[data-testid="strength-bar"]').should('have.class', 'weak');

    // Clear and type a medium strength password
    cy.get('[data-testid="password-input"]').clear();
    cy.get('[data-testid="password-input"]').type('Pass123');
    cy.get('[data-testid="strength-level"]').should('contain', 'Medium');
    cy.get('[data-testid="strength-bar"]').should('have.class', 'medium');

    // Clear and type a strong password
    cy.get('[data-testid="password-input"]').clear();
    cy.get('[data-testid="password-input"]').type('SecurePass123!@#');
    cy.get('[data-testid="strength-level"]').should('contain', 'Strong');
    cy.get('[data-testid="strength-bar"]').should('have.class', 'strong');

    // Verify strength requirements checklist appears
    cy.get('[data-testid="requirement-uppercase"]').should('contain', 'Uppercase letter');
    cy.get('[data-testid="requirement-number"]').should('contain', 'Number');
    cy.get('[data-testid="requirement-special"]').should('contain', 'Special character');

    // Submit button should be enabled
    cy.get('[data-testid="submit-button"]').should('not.be.disabled');
  });

  it('should show visual feedback for empty and very weak passwords', () => {
    // Field starts empty
    cy.get('[data-testid="password-input"]').should('have.value', '');
    cy.get('[data-testid="strength-indicator"]').should('not.exist');

    // Type only spaces
    cy.get('[data-testid="password-input"]').type('   ');
    cy.get('[data-testid="strength-level"]').should('contain', 'Very Weak');
    cy.get('[data-testid="strength-bar"]').should('have.class', 'very-weak');

    // Type single character
    cy.get('[data-testid="password-input"]').clear();
    cy.get('[data-testid="password-input"]').type('a');
    cy.get('[data-testid="strength-level"]').should('contain', 'Very Weak');

    // Verify requirements show as unfulfilled
    cy.get('[data-testid="requirement-uppercase"]').should('have.class', 'unfulfilled');
    cy.get('[data-testid="requirement-number"]').should('have.class', 'unfulfilled');

    // Submit button should be disabled
