describe('Currency Field Formatting', () => {
  beforeEach(() => {
    cy.visit('/forms/currency-input');
  });

  it('should format currency input with commas and two decimal places on valid entry', () => {
    // Test happy path: user enters a large number that should be formatted
    cy.get('[data-testid="currency-input"]').click();
    cy.get('[data-testid="currency-input"]').type('1000000.5');

    // Trigger blur to ensure formatting is applied
    cy.get('[data-testid="currency-input"]').blur();

    // Verify the input displays formatted value with commas and exactly 2 decimal places
    cy.get('[data-testid="currency-input"]').should('have.value', '1,000,000.50');

    // Submit the form to verify the formatted value is processed correctly
    cy.get('[data-testid="submit-btn"]').click();

    // Intercept the API call and verify the value sent to backend
    cy.intercept('POST', '/api/payment/process').as('processPayment');
    cy.wait('@processPayment').then((interception) => {
      expect(interception.request.body.amount).to.equal(1000000.50);
    });

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Payment processed successfully');
  });

  it('should handle edge case of zero, negative values, and invalid characters gracefully', () => {
    // Test negative/edge case: invalid input attempts
    cy.get('[data-testid="currency-input"]').click();
    cy.get('[data-testid="currency-input"]').type('abc123xyz');

    cy.get('[data-testid="currency-input"]').blur();

    // Should strip invalid characters and format only numeric portion
    cy.get('[data-testid="currency-input"]').should('have.value', '123.00');

    // Test with negative value
    cy.get('[data-testid="currency-input"]').clear();
    cy.get('[data-testid="currency-input"]').type('-5000.999');

    cy.get('[data-testid="currency-input"]').blur();

    // Should format negative value with commas and round to 2 decimal places
    cy.get('[data-testid="currency-input"]').should('have.value', '-5,000.99');

    // Test with zero
    cy.get('[data-testid="currency-input"]').clear();
    cy.get('[data-testid="currency-input"]').type('0');

    cy.get('[data-testid="currency-input"]').blur();

    cy.get('[data-testid="currency-input"]').should('have.value', '0.00');

