    cy.get('[data-testid="file-size-display"]').should('have.class', 'size-warning');

    // Upload button should be disabled
    cy.get('[data-testid="upload-button"]').should('be.disabled');

    // Clicking disabled button should not trigger upload
    cy.get('[data-testid="upload-button"]').click({ force: true });
    cy.intercept('POST', '/api/files/upload').as('uploadFile');
    cy.wait('@uploadFile', { timeout: 2000 }).then(() => {
      throw new Error('Upload should not be called');
    }).catch(err => {
      // Expected behavior - upload should not be called
      expect(err.message).to.include('Timed out waiting');
    });

    // Verify error persists
    cy.get('[data-testid="error-message"]').should('be.visible');
