  });

  it('should auto-save form data as draft every 30 seconds', () => {
    cy.intercept('POST', '/api/drafts/save').as('saveDraft');

    // Fill form fields
    cy.get('[data-testid="form-name-input"]').type('John Doe');
    cy.get('[data-testid="form-email-input"]').type('john@example.com');
    cy.get('[data-testid="form-message-textarea"]').type('This is my test message');

    // Wait for first auto-save (30 seconds)
    cy.wait('@saveDraft', { timeout: 35000 });

    // Verify draft was saved with correct data
    cy.wait('@saveDraft').then((interception) => {
      expect(interception.request.body).to.include({
        name: 'John Doe',
        email: 'john@example.com',
        message: 'This is my test message',
      });
