    // Wait for failed auto-save
    cy.wait('@saveDraftError', { timeout: 35000 });

    // Verify error notification appears
    cy.get('[data-testid="draft-error-notification"]').should('be.visible');
    cy.get('[data-testid="draft-error-notification"]').should('contain', 'Failed to save draft');

