describe('Form Submission - Confirmation Email', () => {
  beforeEach(() => {
    cy.visit('/contact-form');
  });

  it('should send confirmation email after successful form submission', () => {
    // Intercept the form submission API and email service call
    cy.intercept('POST', '/api/contact-form').as('formSubmit');
    cy.intercept('POST', '/api/email/send-confirmation').as('emailSend');

    // Fill in form fields
    cy.get('[data-testid="input-name"]').type('John Doe');
    cy.get('[data-testid="input-email"]').type('john.doe@example.com');
    cy.get('[data-testid="input-subject"]').type('Test Inquiry');
    cy.get('[data-testid="textarea-message"]').type('This is a test message for form submission.');

    // Submit the form
    cy.get('[data-testid="button-submit"]').click();

    // Wait for form submission API call
    cy.wait('@formSubmit').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Wait for confirmation email API call
    cy.wait('@emailSend').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
      expect(interception.request.body).to.include('john.doe@example.com');
    });

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .should('contain', 'Confirmation email has been sent');

    // Verify form is cleared or redirected
    cy.get('[data-testid="input-name"]').should('have.value', '');
  });

  it('should handle email delivery failure and show error message', () => {
    // Intercept form submission successfully but email sending fails
    cy.intercept('POST', '/api/contact-form').as('formSubmit');
    cy.intercept('POST', '/api/email/send-confirmation', {
      statusCode: 500,
      body: { error: 'Email service unavailable' }
    }).as('emailSendFail');

    // Fill in form with invalid email format (edge case)
    cy.get('[data-testid="input-name"]').type('Jane Smith');
    cy.get('[data-testid="input-email"]').type('invalid-email-format');
    cy.get('[data-testid="input-subject"]').type('Support Request');
    cy.get('[data-testid="textarea-message"]').type('Please help me with this issue.');

    // Click submit
    cy.get('[data-testid="button-submit"]').click();

    // Verify email validation error appears
    cy.get('[data-testid="error-email"]')
      .should('be.visible')
      .should('contain', 'Please enter a valid email address');

    // Form should not submit
    cy.get('[data-testid="success-message"]').should('not.exist');
  });
});

