    // Header should remain sticky after navigation
    cy.get('[data-testid="header"]').should('be.visible');
    cy.get('[data-testid="header"]').should('have.css', 'position', 'sticky');
  });

  it('should handle edge case where header z-index prevents content interaction', () => {
    // Scroll to ensure header is visible
    cy.scrollTo(0, 100);

    // Get header and verify z-index is set appropriately
    cy.get('[data-testid="header"]').should('have.css', 'z-index').and('not.equal', 'auto');

    // Verify content below header is still clickable (header should not block it)
    cy.get('[data-testid="main-content"]').should('be.visible');
    cy.get('[data-testid="hero-button"]').should('be.visible').click();

    // Verify button interaction was successful
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Success');

    // Test that header doesn't overlap critical content
    cy.get('[data-testid="header"]').then(($header) => {
      cy.get('[data-testid="main-content"]').then(($content) => {
        const headerHeight = $header.outerHeight();
        const contentTop = $content.offset().top;
        expect(contentTop).to.be.greaterThan(headerHeight);
      });
    });

    // Scroll back to top and verify header position
    cy.scrollTo('top');
    cy.get('[data-testid="header"]').should('have.css', 'top', '0px');
    cy.get('[data-testid="header"]').should('be.visible');
  });
});

describe('Dropdown Navigation with Arrow Keys', () => {
  beforeEach(() => {
    cy.visit('/dropdown-menu');
  });

  it('should navigate dropdown items using arrow keys and select with Enter', () => {
    // Open the dropdown menu
    cy.get('[data-testid="dropdown-trigger"]').click();
    cy.get('[data-testid="dropdown-menu"]').should('be.visible');

    // First item should be focused by default
    cy.get('[data-testid="dropdown-item-0"]').should('have.class', 'focused');

    // Navigate down to second item
    cy.get('[data-testid="dropdown-menu"]').type('{downarrow}');
    cy.get('[data-testid="dropdown-item-1"]').should('have.class', 'focused');
    cy.get('[data-testid="dropdown-item-0"]').should('not.have.class', 'focused');

    // Navigate down to third item
    cy.get('[data-testid="dropdown-menu"]').type('{downarrow}');
    cy.get('[data-testid="dropdown-item-2"]').should('have.class', 'focused');

    // Navigate back up to second item
    cy.get('[data-testid="dropdown-menu"]').type('{uparrow}');
    cy.get('[data-testid="dropdown-item-1"]').should('have.class', 'focused');
    cy.get('[data-testid="dropdown-item-2"]').should('not.have.class', 'focused');

    // Select the focused item with Enter
    cy.get('[data-testid="dropdown-menu"]').type('{enter}');
    cy.get('[data-testid="dropdown-selected-value"]').should('contain', 'Option 2');
    cy.get('[data-testid="dropdown-menu"]').should('not.be.visible');
  });

  it('should handle edge cases - wrap around and disabled items', () => {
    // Open the dropdown
    cy.get('[data-testid="dropdown-trigger"]').click();
    cy.get('[data-testid="dropdown-menu"]').should('be.visible');

    // Navigate to last item
    cy.get('[data-testid="dropdown-menu"]').type('{downarrow}{downarrow}{downarrow}{downarrow}');
    cy.get('[data-testid="dropdown-item-4"]').should('have.class', 'focused');

    // Press down arrow again - should wrap to first item
    cy.get('[data-testid="dropdown-menu"]').type('{downarrow}');
    cy.get('[data-testid="dropdown-item-0"]').should('have.class', 'focused');

    // Press up arrow - should wrap to last item
    cy.get('[data-testid="dropdown-menu"]').type('{uparrow}');
    cy.get('[data-testid="dropdown-item-4"]').should('have.class', 'focused');

    // Test disabled item - navigate to item 3 which is disabled
    cy.get('[data-testid="dropdown-menu"]').type('{uparrow}{uparrow}');
    cy.get('[data-testid="dropdown-item-2"]').should('have.class', 'focused');
    cy.get('[data-testid="dropdown-item-3"]').should('have.attr', 'aria-disabled', 'true');

    // Attempt to press Enter on disabled item should not select it
    cy.get('[data-testid="dropdown-menu"]').type('{enter}');
    cy.get('[data-testid="dropdown-selected-value"]').should('contain', 'Option 3');
    cy.get('[data-testid="dropdown-menu"]').should('not.be.visible');
  });
});

