describe('Data Auto-Refresh After Mutation', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should automatically refresh data display after successful mutation', () => {
    // Intercept the initial GET request for data
    cy.intercept('GET', '/api/items').as('getItems');
    cy.wait('@getItems');

    // Verify initial data is displayed
    cy.get('[data-testid="item-list"]').should('be.visible');
    cy.get('[data-testid="item-count"]').should('contain', '5');

    // Intercept the mutation request
    cy.intercept('POST', '/api/items', {
      statusCode: 200,
      body: { id: 6, name: 'New Item', status: 'active' },
    }).as('createItem');

    // Intercept the automatic refresh GET request
    cy.intercept('GET', '/api/items', {
      statusCode: 200,
      body: [
        { id: 1, name: 'Item 1' },
        { id: 2, name: 'Item 2' },
        { id: 3, name: 'Item 3' },
        { id: 4, name: 'Item 4' },
        { id: 5, name: 'Item 5' },
        { id: 6, name: 'New Item' },
      ],
    }).as('refreshItems');

    // Perform mutation by clicking add button
    cy.get('[data-testid="add-item-btn"]').click();
    cy.get('[data-testid="item-input"]').type('New Item');
    cy.get('[data-testid="submit-btn"]').click();

    // Wait for mutation
    cy.wait('@createItem');

    // Wait for automatic refresh
    cy.wait('@refreshItems');

    // Verify data has been refreshed
    cy.get('[data-testid="item-count"]').should('contain', '6');
    cy.get('[data-testid="item-list"]').should('contain', 'New Item');
  });

  it('should handle failed mutation and not refresh data', () => {
    // Intercept the initial GET request
    cy.intercept('GET', '/api/items').as('getItems');
    cy.wait('@getItems');

    // Verify initial data
    cy.get('[data-testid="item-count"]').should('contain', '5');

    // Intercept failed mutation request
    cy.intercept('POST', '/api/items', {
      statusCode: 500,
      body: { error: 'Server error' },
    }).as('failedCreateItem');

    // Attempt mutation
    cy.get('[data-testid="add-item-btn"]').click();
    cy.get('[data-testid="item-input"]').type('Invalid Item');
    cy.get('[data-testid="submit-btn"]').click();

    // Wait for failed mutation
    cy.wait('@failedCreateItem');

    // Verify error message is shown
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Server error');

    // Verify data count hasn't changed (no refresh occurred)
    cy.get('[data-testid="item-count"]').should('contain', '5');

    // Verify the new item was not added to the list
    cy.get('[data-testid="item-list"]').should('not.contain', 'Invalid Item');
  });
});

describe('Retry Button on Network Timeout', () => {
  beforeEach(() => {
    cy.visit('/network-request-page');
  });

  it('should display retry button and successfully retry after network timeout', () => {
    // Intercept the API call and simulate a timeout on first attempt
    cy.intercept('GET', '/api/data', (req) => {
      req.reply((res) => {
        res.delay(15000); // Simulate timeout
      });
    }).as('firstRequest');

    // Trigger the network request
    cy.get('[data-testid="fetch-data-button"]').click();
    cy.wait('@firstRequest');

    // Verify timeout error message and retry button are visible
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Request timed out');
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Setup successful response for retry
    cy.intercept('GET', '/api/data', {
      statusCode: 200,
      body: { data: 'Success', timestamp: new Date().toISOString() }
    }).as('retryRequest');

    // Click retry button
    cy.get('[data-testid="retry-button"]').click();
    cy.wait('@retryRequest');

    // Verify successful response is displayed
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Data loaded successfully');
    cy.get('[data-testid="data-content"]').should('contain', 'Success');
    cy.get('[data-testid="error-message"]').should('not.exist');
  });

  it('should handle retry button interaction when user clicks retry multiple times during failed request', () => {
    // Intercept API and simulate timeout
    cy.intercept('GET', '/api/data', (req) => {
      req.reply((res) => {
        res.delay(15000);
      });
    }).as('failedRequest');

    cy.get('[data-testid="fetch-data-button"]').click();
    cy.wait('@failedRequest');

    // Verify retry button appears
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Simulate another timeout on first retry attempt
    cy.intercept('GET', '/api/data', (req) => {
      req.reply((res) => {
        res.delay(15000);
      });
    }).as('secondFailedRequest');

    cy.get('[data-testid="retry-button"]').click();
    cy.wait('@secondFailedRequest');

    // Verify retry button is still available and error persists
    cy.get('[data-testid="retry-button"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Request timed out');
    cy.get('[data-testid="retry-attempts-counter"]').should('contain', '2');
  });
});

describe('Optimistic UI Updates - Like Post Feature', () => {
  beforeEach(() => {
    cy.visit('/posts');
    cy.intercept('POST', '/api/posts/*/likes', {
      statusCode: 200,
      body: { success: true, likes: 42 }
    }).as('likePost');
    cy.intercept('GET', '/api/posts', {
      statusCode: 200,
      body: [
        {
          id: 1,
          title: 'Test Post',
          content: 'This is a test post',
          likes: 41,
          liked: false
        }
      ]
    }).as('getPosts');
    cy.wait('@getPosts');
  });

  it('should show optimistic UI update when liking a post and confirm with API response', () => {
    cy.get('[data-testid="post-1"]').should('be.visible');
    cy.get('[data-testid="like-button-1"]').should('contain', '41');
    cy.get('[data-testid="like-button-1"]').should('not.have.class', 'liked');

    // User clicks like button - optimistic update should happen immediately
    cy.get('[data-testid="like-button-1"]').click();

    // Verify optimistic UI update happens before API response
    cy.get('[data-testid="like-button-1"]').should('contain', '42');
    cy.get('[data-testid="like-button-1"]').should('have.class', 'liked');
    cy.get('[data-testid="like-icon-1"]').should('have.attr', 'aria-label', 'Unlike');

    // Wait for API confirmation
    cy.wait('@likePost');

    // Verify state persists after API response
    cy.get('[data-testid="like-button-1"]').should('contain', '42');
    cy.get('[data-testid="like-button-1"]').should('have.class', 'liked');
  });

  it('should rollback optimistic update if API request fails', () => {
    cy.intercept('POST', '/api/posts/*/likes', {
      statusCode: 500,
      body: { error: 'Server error' }
    }).as('likePostFail');

    cy.get('[data-testid="like-button-1"]').should('contain', '41');

    // User clicks like button - optimistic update shows immediately
    cy.get('[data-testid="like-button-1"]').click();
    cy.get('[data-testid="like-button-1"]').should('contain', '42');
    cy.get('[data-testid="like-button-1"]').should('have.class', 'liked');

    // Wait for API failure
    cy.wait('@likePostFail');

    // Verify rollback to original state
    cy.get('[data-testid="like-button-1"]').should('contain', '41');
    cy.get('[data-testid="like-button-1"]').should('not.have.class', 'liked');
    cy.get('[data-testid="error-toast"]').should('be.visible');
    cy.get('[data-testid="error-toast"]').should('contain', 'Failed to like post');
  });
});

describe('Stale Data Invalidation After Form Submission', () => {
  beforeEach(() => {
    cy.visit('/form-page');
  });

  it('should invalidate stale data after successful form submission', () => {
    // Intercept initial data fetch
    cy.intercept('GET', '/api/user-data').as('initialDataFetch');
    cy.wait('@initialDataFetch');

    // Verify initial stale data is displayed
    cy.get('[data-testid="user-name"]').should('contain', 'John Doe');
    cy.get('[data-testid="user-email"]').should('contain', 'john@example.com');

    // Fill form with new data
    cy.get('[data-testid="form-name-input"]').type('Jane Smith');
    cy.get('[data-testid="form-email-input"]').clear().type('jane@example.com');

    // Intercept form submission
    cy.intercept('POST', '/api/update-user').as('formSubmit');

    // Submit form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for successful submission
    cy.wait('@formSubmit').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Intercept refreshed data endpoint
    cy.intercept('GET', '/api/user-data').as('refreshedDataFetch');
    cy.wait('@refreshedDataFetch');

    // Verify stale data has been invalidated and updated
    cy.get('[data-testid="user-name"]').should('contain', 'Jane Smith');
    cy.get('[data-testid="user-email"]').should('contain', 'jane@example.com');
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Data updated successfully');
  });

  it('should not invalidate stale data when form submission fails', () => {
    // Intercept initial data fetch
    cy.intercept('GET', '/api/user-data').as('initialDataFetch');
    cy.wait('@initialDataFetch');

    // Verify initial stale data is displayed
    cy.get('[data-testid="user-name"]').should('contain', 'John Doe');
    cy.get('[data-testid="user-email"]').should('contain', 'john@example.com');

    // Fill form with invalid data
    cy.get('[data-testid="form-name-input"]').type('');
    cy.get('[data-testid="form-email-input"]').clear().type('invalid-email');

    // Intercept failed form submission
    cy.intercept('POST', '/api/update-user', { statusCode: 400, body: { error: 'Validation failed' } }).as('failedSubmit');

    // Attempt to submit form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for failed submission
    cy.wait('@failedSubmit');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Validation failed');

    // Verify stale data remains unchanged (NOT invalidated)
    cy.get('[data-testid="user-name"]').should('contain', 'John Doe');
    cy.get('[data-testid="user-email"]').should('contain', 'john@example.com');
    cy.get('[data-testid="success-message"]').should('not.exist');
  });
});

