describe('Polling stops when navigating away from page', () => {
  beforeEach(() => {
    cy.visit('/polling-dashboard');
  });

  it('should stop polling API calls when user navigates to a different page', () => {
    // Setup: Intercept the polling API endpoint
    cy.intercept('GET', '/api/polling/data').as('pollingRequest');

    // Verify initial page is loaded
    cy.get('[data-testid="polling-status"]').should('be.visible');

    // Wait for first polling request
    cy.wait('@pollingRequest');

    // Wait for second polling request to confirm polling is active
    cy.wait('@pollingRequest');

    // Verify polling indicator shows active status
    cy.get('[data-testid="polling-indicator"]').should('contain', 'Active');

    // Navigate away from the page
    cy.get('[data-testid="nav-home"]').click();

    // Verify navigation occurred
    cy.url().should('include', '/home');

    // Wait to ensure polling would have made additional requests
    cy.wait(3000);

    // Verify no additional polling requests were made after navigation
    cy.intercept('GET', '/api/polling/data').as('pollAfterNav');
    cy.wait('@pollAfterNav', { timeout: 2000 }).then(() => {
      throw new Error('Polling should have stopped');
    }).catch((err) => {
      if (err.message !== 'Polling should have stopped') {
        // Expected: timeout means no request was made
        expect(true).to.be.true;
      }
    });
  });

  it('should handle rapid navigation without memory leaks or lingering requests', () => {
    // Setup: Intercept polling endpoint
    cy.intercept('GET', '/api/polling/data').as('pollingRequest');

    // Wait for initial polling to start
    cy.wait('@pollingRequest');

    // Rapidly navigate to multiple pages
    cy.get('[data-testid="nav-profile"]').click();
    cy.url().should('include', '/profile');

    cy.get('[data-testid="nav-settings"]').click();
    cy.url().should('include', '/settings');

    cy.get('[data-testid="nav-dashboard"]').click();
    cy.url().should('include', '/dashboard');

