    cy.visit('/polling-dashboard');

    // Verify polling restarts cleanly
    cy.get('[data-testid="polling-status"]').should('be.visible');
    cy.get('[data-testid="polling-indicator"]').should('contain', 'Active');

    // Verify new polling requests are being made
    cy.wait('@pollingRequest');
    cy.wait('@pollingRequest');

    // Verify data is being updated correctly
    cy.get('[data-testid="polling-data"]').should('not.be.empty');
