describe('API Response Caching - Instant Repeat Visits', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should cache API responses and load instantly on repeat visits', () => {
    // First visit - API call should be made
    cy.intercept('GET', '/api/user/profile').as('firstProfileFetch');
    cy.get('[data-testid="load-profile-btn"]').click();
    cy.wait('@firstProfileFetch');

    cy.get('[data-testid="profile-name"]').should('be.visible').should('contain', 'John Doe');
    cy.get('[data-testid="profile-email"]').should('contain', 'john@example.com');

    // Record initial load time
    let firstLoadTime = 0;
    cy.window().then((win) => {
      firstLoadTime = win.performance.now();
    });

    // Navigate away and back
    cy.visit('/settings');
    cy.visit('/dashboard');

    // Second visit - should use cache, no new API call
    cy.intercept('GET', '/api/user/profile', (req) => {
      req.reply({ fixture: 'profile.json' });
    }).as('cachedProfileFetch');

    cy.get('[data-testid="load-profile-btn"]').click();

    // Verify cached data appears instantly without new network request
    cy.get('[data-testid="profile-name"]').should('be.visible').should('contain', 'John Doe');
    cy.get('[data-testid="cache-indicator"]').should('contain', 'Loaded from cache');

    // Verify response time is significantly faster (under 100ms for cached)
    cy.window().then((win) => {
      const secondLoadTime = win.performance.now() - firstLoadTime;
      expect(secondLoadTime).to.be.lessThan(100);
    });
  });

  it('should invalidate cache when refresh is triggered or cache expires', () => {
    // First API call
    cy.intercept('GET', '/api/user/profile').as('initialFetch');
    cy.get('[data-testid="load-profile-btn"]').click();
    cy.wait('@initialFetch');

    cy.get('[data-testid="profile-name"]').should('be.visible').should('contain', 'John Doe');

    // Trigger cache refresh
    cy.intercept('GET', '/api/user/profile', {
      statusCode: 200,
      body: { name: 'Jane Doe', email: 'jane@example.com' }
    }).as('refreshedFetch');

    cy.get('[data-testid="refresh-cache-btn"]').click();
    cy.wait('@refreshedFetch');

    // Verify fresh data is loaded
    cy.get('[data-testid="profile-name"]').should('contain', 'Jane Doe');
    cy.get('[data-testid="cache-indicator"]').should('not.exist');

    // Verify cache was cleared with manual refresh
    cy.get('[data-testid="cache-status"]').should('contain', 'Cache cleared');

    // Simulate cache expiration timeout
    cy.clock();
    cy.tick(3600000); // 1 hour expiration

    // Next request should bypass cache
    cy.intercept('GET', '/api/user/profile').as('expiredCacheFetch');
    cy.get('[data-testid="load-profile-btn"]').click();
    cy.wait('@expiredCacheFetch');

    cy.get('[data-testid="cache-indicator"]').should('not.exist');
  });
});

