describe('Internet Connection Drop - Friendly Error Message', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should display friendly error message when connection is lost', () => {
    // Setup: Wait for initial page load
    cy.get('[data-testid="main-content"]').should('be.visible');
    cy.get('[data-testid="connection-status"]').should('contain', 'Connected');

    // Simulate network request
    cy.intercept('GET', '/api/user-data').as('getUserData');
    cy.get('[data-testid="load-data-btn"]').click();
    cy.wait('@getUserData');

    // Simulate connection drop by intercepting with offline response
    cy.intercept('GET', '/api/user-data', {
      forceNetworkError: true
    }).as('connectionDropped');

    cy.get('[data-testid="refresh-btn"]').click();
    cy.wait('@connectionDropped');

    // Assert friendly error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Connection Lost');
    cy.get('[data-testid="error-message"]').should('contain', 'Please check your internet connection');

    // Assert error icon/styling is present
    cy.get('[data-testid="error-icon"]').should('be.visible');

    // Assert retry button is available
    cy.get('[data-testid="retry-btn"]').should('be.visible');
    cy.get('[data-testid="retry-btn"]').should('contain', 'Retry');
  });

  it('should handle multiple consecutive connection failures gracefully', () => {
    cy.get('[data-testid="main-content"]').should('be.visible');

    // First connection attempt
    cy.intercept('GET', '/api/user-data', {
      forceNetworkError: true
    }).as('firstFailure');

    cy.get('[data-testid="load-data-btn"]').click();
    cy.wait('@firstFailure');

    cy.get('[data-testid="error-message"]').should('contain', 'Connection Lost');

    // Second connection attempt (still failing)
    cy.intercept('GET', '/api/user-data', {
      forceNetworkError: true
    }).as('secondFailure');

    cy.get('[data-testid="retry-btn"]').click();
    cy.wait('@secondFailure');

    // Error message should still be visible and not duplicate
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('have.length', 1);

    // Assert helpful suggestions are displayed
    cy.get('[data-testid="error-suggestions"]').should('be.visible');
    cy.get('[data-testid="error-suggestions"]').should('contain', 'troubleshoot');
  });
});

