    cy.get('[data-testid="email-error"]').should('have.attr', 'aria-live', 'polite');

    // Verify error message has role="alert" for immediate screen reader notification
    cy.get('[data-testid="email-error"]').should('have.attr', 'role', 'alert');

    // Verify error message contains descriptive text
    cy.get('[data-testid="email-error"]').should('contain', 'Please enter a valid email address');

    // Verify input has aria-describedby pointing to error message ID
    cy.get('[data-testid="email-input"]').should('have.attr', 'aria-describedby', 'email-error');

    // Verify input has aria-invalid state
    cy.get('[data-testid="email-input"]').should('have.attr', 'aria-invalid', 'true');
  });

  it('should handle multiple error messages with proper ARIA labels and associations', () => {
    // Negative case: Submit empty form with multiple fields
    cy.get('[data-testid="submit-button"]').click();

    // Verify all error messages are visible
    cy.get('[data-testid="email-error"]').should('be.visible');
    cy.get('[data-testid="password-error"]').should('be.visible');
    cy.get('[data-testid="name-error"]').should('be.visible');

    // Verify each error has aria-live="polite" for dynamic announcements
    cy.get('[data-testid="email-error"]').should('have.attr', 'aria-live', 'polite');
    cy.get('[data-testid="password-error"]').should('have.attr', 'aria-live', 'polite');

    // Verify error container has aria-label for context
    cy.get('[data-testid="error-container"]').should('have.attr', 'aria-label').and('contain', 'Form errors');

    // Verify all inputs have aria-invalid="true"
    cy.get('[data-testid="email-input"]').should('have.attr', 'aria-invalid', 'true');
    cy.get('[data-testid="password-input"]').should('have.attr', 'aria-invalid', 'true');

    // Verify error messages are not hidden from screen readers
    cy.get('[data-testid="email-error"]').should('not.have.css', 'display', 'none');
    cy.get('[data-testid="password-error"]').should('not.have.css', 'display', 'none');
  });
});

