describe('Async Error Retry Functionality', () => {
  beforeEach(() => {
    cy.visit('/async-operations');
  });

  it('should display retry option when async operation fails', () => {
    // Intercept the initial async request and simulate failure
    cy.intercept('POST', '/api/async-operation', {
      statusCode: 500,
      body: { error: 'Server error' }
    }).as('asyncFailure');

    // Click button to trigger async operation
    cy.get('[data-testid="async-operation-btn"]').click();

    // Wait for the failed request
    cy.wait('@asyncFailure');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Operation failed');

    // Verify retry button is visible
    cy.get('[data-testid="retry-btn"]')
      .should('be.visible')
      .should('contain', 'Retry');

    // Now intercept the retry request with success
    cy.intercept('POST', '/api/async-operation', {
      statusCode: 200,
      body: { success: true, data: 'Operation completed' }
    }).as('asyncSuccess');

    // Click retry button
    cy.get('[data-testid="retry-btn"]').click();

    // Wait for successful request
    cy.wait('@asyncSuccess');

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .should('contain', 'Operation completed successfully');

    // Verify error and retry button are no longer visible
    cy.get('[data-testid="error-message"]').should('not.exist');
    cy.get('[data-testid="retry-btn"]').should('not.exist');
  });

  it('should handle multiple retry failures with increasing backoff', () => {
    let requestCount = 0;

    // Intercept requests and fail first two attempts
    cy.intercept('POST', '/api/async-operation', (req) => {
      requestCount++;
      if (requestCount < 3) {
        req.reply({
          statusCode: 503,
          body: { error: 'Service temporarily unavailable' }
        });
      } else {
        req.reply({
          statusCode: 200,
          body: { success: true, data: 'Finally succeeded' }
        });
      }
    }).as('asyncWithRetries');

    // Trigger initial operation
    cy.get('[data-testid="async-operation-btn"]').click();
    cy.wait('@asyncWithRetries');

    // Verify first failure
    cy.get('[data-testid="error-message"]')
      .should('be.visible');
    cy.get('[data-testid="retry-btn"]')
      .should('be.visible');

    // First retry
    cy.get('[data-testid="retry-btn"]').click();
    cy.wait('@asyncWithRetries');

    // Verify second failure still shows retry option
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Service temporarily unavailable');
    cy.get('[data-testid="retry-btn"]')
      .should('be.visible');

    // Second retry succeeds
    cy.get('[data-testid="retry-btn"]').click();
    cy.wait('@asyncWithRetries');

    // Verify final success
    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .should('contain', 'Finally succeeded');
    cy.get('[data-testid="error-message"]').should('not.exist');
  });
});

describe('Long-running Task Persistence Across Page Refreshes', () => {
  beforeEach(() => {
    cy.visit('/tasks');
  });

  it('should persist task progress when page is refreshed during execution', () => {
    // Start a long-running task
    cy.get('[data-testid="start-task-button"]').click();
    cy.get('[data-testid="task-name-input"]').type('ProcessData');
    cy.get('[data-testid="submit-task-button"]').click();

    // Verify task has started
    cy.get('[data-testid="task-status"]').should('contain', 'Running');
    cy.get('[data-testid="task-progress"]').should('be.visible');

    // Intercept the task status API call
    cy.intercept('GET', '/api/tasks/status/*').as('getTaskStatus');
    cy.wait('@getTaskStatus');

    // Get the task ID before refresh
    cy.get('[data-testid="task-id"]').invoke('text').then((taskId) => {
      // Refresh the page mid-execution
      cy.reload();

      // Verify page loads and task is still present
      cy.get('[data-testid="task-list"]').should('be.visible');

      // Intercept status check after reload
      cy.intercept('GET', '/api/tasks/status/*').as('getTaskStatusAfterRefresh');
      cy.wait('@getTaskStatusAfterRefresh');

      // Verify task persists with same ID
      cy.get('[data-testid="task-id"]').should('contain', taskId);
      cy.get('[data-testid="task-status"]').should('contain', 'Running');
      cy.get('[data-testid="task-progress"]').should('be.visible');
    });

    // Wait for task completion
    cy.get('[data-testid="task-status"]', { timeout: 30000 }).should('contain', 'Completed');
    cy.get('[data-testid="task-result"]').should('be.visible');
  });

  it('should handle missing task data gracefully when session storage is corrupted', () => {
    // Start a task
    cy.get('[data-testid="start-task-button"]').click();
    cy.get('[data-testid="task-name-input"]').type('CorruptedTask');
    cy.get('[data-testid="submit-task-button"]').click();

    // Verify task started
    cy.get('[data-testid="task-status"]').should('contain', 'Running');

    // Corrupt the local/session storage
    cy.window().then((win) => {
      win.sessionStorage.clear();
      win.localStorage.clear();
    });

    // Intercept API to simulate task not found
    cy.intercept('GET', '/api/tasks/status/*', {
      statusCode: 404,
      body: { error: 'Task not found' }
    }).as('taskNotFound');

    // Refresh page with corrupted storage
    cy.reload();

    // Wait for the API call
    cy.wait('@taskNotFound');

    // Verify appropriate error message is shown
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Task could not be restored');

    // Verify user can start a new task instead
    cy.get('[data-testid="start-task-button"]').should('be.visible').click();
    cy.get('[data-testid="task-name-input"]').type('NewTask');
    cy.get('[data-testid="submit-task-button"]').click();

    cy.get('[data-testid="task-status"]').should('contain', 'Running');
  });
});

