      });

    // Scroll within modal content
    cy.get('[data-testid="modal-content-scrollable"]').scrollTo(0, 300);

    // Verify scroll position changed within modal
    cy.get('[data-testid="modal-content-scrollable"]').then(($el) => {
      expect($el[0].scrollTop).to.equal(300);
    });

    // Verify body/page scroll position did not change
