describe('Modal Scroll Lock Functionality', () => {
  beforeEach(() => {
    cy.visit('/modal-test');
  });

  it('should prevent page scroll when modal is open', () => {
    // Verify body is scrollable before modal opens
    cy.get('body').should('have.css', 'overflow', 'visible');

    // Scroll page to verify it's scrollable
    cy.scrollTo(0, 100);
    cy.window().then((win) => {
      expect(win.scrollY).to.be.greaterThan(0);
    });

    // Reset scroll position
    cy.scrollTo(0, 0);

    // Open modal
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal-overlay"]').should('be.visible');

    // Verify body scroll is locked
    cy.get('body').should('have.css', 'overflow', 'hidden');

    // Attempt to scroll and verify scroll position doesn't change
    cy.window().then((win) => {
      const initialScrollY = win.scrollY;
      cy.scrollTo(0, 200);
      cy.window().then((win2) => {
        expect(win2.scrollY).to.equal(initialScrollY);
      });
    });

    // Verify modal is still visible and properly displayed
    cy.get('[data-testid="modal-content"]').should('be.visible');
  });

  it('should restore page scroll when modal is closed', () => {
    // Open modal
    cy.get('[data-testid="open-modal-btn"]').click();
