describe('Modal with Tabbed Content - Remember Active Tab', () => {
  beforeEach(() => {
    cy.visit('/modal-tabs');
  });

  it('should remember the active tab when modal is closed and reopened', () => {
    // Open the modal
    cy.get('[data-testid="open-modal-button"]').click();
    cy.get('[data-testid="modal-container"]').should('be.visible');

    // Verify first tab is active by default
    cy.get('[data-testid="tab-panel-1"]').should('be.visible');
    cy.get('[data-testid="tab-button-1"]').should('have.attr', 'aria-selected', 'true');

    // Click on the second tab
    cy.get('[data-testid="tab-button-2"]').click();
    cy.get('[data-testid="tab-panel-2"]').should('be.visible');
    cy.get('[data-testid="tab-button-2"]').should('have.attr', 'aria-selected', 'true');

    // Verify tab 1 is no longer visible
    cy.get('[data-testid="tab-panel-1"]').should('not.be.visible');

    // Close the modal
    cy.get('[data-testid="modal-close-button"]').click();
    cy.get('[data-testid="modal-container"]').should('not.exist');

    // Reopen the modal
    cy.get('[data-testid="open-modal-button"]').click();
    cy.get('[data-testid="modal-container"]').should('be.visible');

    // Verify tab 2 is still active (remembered state)
    cy.get('[data-testid="tab-panel-2"]').should('be.visible');
    cy.get('[data-testid="tab-button-2"]').should('have.attr', 'aria-selected', 'true');
    cy.get('[data-testid="tab-panel-1"]').should('not.be.visible');

    // Verify tab content is intact
    cy.get('[data-testid="tab-panel-2"]').should('contain', 'Tab 2 Content');
  });

  it('should handle tab switching with persistence across page reload', () => {
    cy.get('[data-testid="open-modal-button"]').click();
    cy.get('[data-testid="modal-container"]').should('be.visible');

    // Switch to third tab
    cy.get('[data-testid="tab-button-3"]').click();
    cy.get('[data-testid="tab-panel-3"]').should('be.visible');
    cy.get('[data-testid="tab-button-3"]').should('have.attr', 'aria-selected', 'true');

    // Reload the page
    cy.reload();

    // Modal should not be visible after reload (expected behavior)
    cy.get('[data-testid="modal-container"]').should('not.exist');

    // Reopen modal
    cy.get('[data-testid="open-modal-button"]').click();
    cy.get('[data-testid="modal-container"]').should('be.visible');

    // Tab state should not persist across page reload (localStorage cleared)
    // First tab should be active instead
    cy.get('[data-testid="tab-button-1"]').should('have.attr', 'aria-selected', 'true');
    cy.get('[data-testid="tab-panel-1"]').should('be.visible');

    // Verify we can still switch tabs within the session
    cy.get('[data-testid="tab-button-3"]').click();
    cy.get('[data-testid="tab-panel-3"]').should('be.visible');
  });
});

describe('Cookie Consent Banner', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.clearCookies();
  });

  it('should display and hide cookie consent banner after accepting', () => {
    // Verify banner is visible on page load
    cy.get('[data-testid="cookie-consent-banner"]').should('be.visible');
    cy.get('[data-testid="cookie-consent-title"]').should('contain', 'Cookie Consent');
    cy.get('[data-testid="cookie-consent-description"]').should('contain', 'We use cookies');

    // Verify accept button exists and is clickable
    cy.get('[data-testid="cookie-accept-button"]').should('be.visible');
    cy.get('[data-testid="cookie-reject-button"]').should('be.visible');

    // Intercept the consent API call
    cy.intercept('POST', '/api/consent/accept').as('acceptConsent');

    // Click accept button
    cy.get('[data-testid="cookie-accept-button"]').click();

    // Wait for API response
    cy.wait('@acceptConsent');

    // Verify banner disappears
    cy.get('[data-testid="cookie-consent-banner"]').should('not.exist');

    // Verify consent cookie is set
    cy.getCookie('consent_accepted').should('exist');
    cy.getCookie('consent_accepted').should('have.property', 'value', 'true');

    // Verify banner does not reappear on page reload
    cy.reload();
    cy.get('[data-testid="cookie-consent-banner"]').should('not.exist');
  });

  it('should handle reject action and allow dismissal with different cookie value', () => {
    // Verify banner is visible
    cy.get('[data-testid="cookie-consent-banner"]').should('be.visible');

    // Intercept the reject API call
    cy.intercept('POST', '/api/consent/reject').as('rejectConsent');

    // Click reject button
    cy.get('[data-testid="cookie-reject-button"]').click();

    // Wait for API response
    cy.wait('@rejectConsent');

    // Verify banner disappears after rejection
    cy.get('[data-testid="cookie-consent-banner"]').should('not.exist');

    // Verify rejection cookie is set with different value
    cy.getCookie('consent_accepted').should('exist');
    cy.getCookie('consent_accepted').should('have.property', 'value', 'false');

    // Verify banner does not reappear on reload after rejection
    cy.reload();
    cy.get('[data-testid="cookie-consent-banner"]').should('not.exist');
  });
});

