  });

  it('should sort table in ascending order when clicking column header', () => {
    // Verify initial table state
    cy.get('[data-testid="table-container"]').should('be.visible');

    // Get initial row values
    cy.get('[data-testid="table-body"] tr').first().within(() => {
      cy.get('[data-testid="name-cell"]').invoke('text').as('firstRowBefore');
    });

    // Click on Name column header to sort
    cy.get('[data-testid="column-header-name"]').click();

    // Wait for sort API call
    cy.intercept('GET', '/api/table/sort?column=name&order=asc').as('sortAsc');
    cy.wait('@sortAsc');

    // Verify table is sorted in ascending order
    cy.get('[data-testid="table-body"] tr').then((rows) => {
      const firstValue = rows.eq(0).find('[data-testid="name-cell"]').text();
      const secondValue = rows.eq(1).find('[data-testid="name-cell"]').text();
      expect(firstValue.localeCompare(secondValue)).to.be.lte(0);
    });

    // Verify sort indicator is visible
    cy.get('[data-testid="sort-indicator-name"]').should('be.visible').should('contain', '↑');
