describe('Freeze First Column on Horizontal Scroll', () => {
  beforeEach(() => {
    cy.visit('/table');
  });

  it('should freeze the first column when scrolling horizontally', () => {
    // Verify table is visible
    cy.get('[data-testid="data-table"]').should('be.visible');

    // Verify first column is visible before scroll
    cy.get('[data-testid="table-column-id"]').should('be.visible');
    cy.get('[data-testid="table-column-id"]').should('contain', 'ID');

    // Get initial position of first column
    cy.get('[data-testid="table-column-id"]').then(($col) => {
      const initialLeft = $col[0].getBoundingClientRect().left;
      cy.wrap(initialLeft).as('initialPosition');
    });

    // Click freeze button on first column header
    cy.get('[data-testid="freeze-column-btn-0"]').click();

    // Verify freeze icon appears
    cy.get('[data-testid="freeze-indicator-0"]').should('be.visible');
    cy.get('[data-testid="freeze-indicator-0"]').should('contain', '📌');

    // Scroll table horizontally
    cy.get('[data-testid="table-scroll-container"]').scrollTo('right');

    // Verify first column remains visible and in same position
    cy.get('[data-testid="table-column-id"]').should('be.visible');
    cy.get('[data-testid="table-column-id"]').then(($col) => {
      const positionAfterScroll = $col[0].getBoundingClientRect().left;
      cy.get('@initialPosition').then((initialLeft) => {
        expect(positionAfterScroll).to.equal(initialLeft);
      });
    });

    // Verify other columns scroll but are hidden behind frozen column
    cy.get('[data-testid="table-column-name"]').should('not.be.visible');
  });

  it('should unfreeze the first column and allow normal scrolling', () => {
    // Setup: freeze the first column
    cy.get('[data-testid="data-table"]').should('be.visible');
    cy.get('[data-testid="freeze-column-btn-0"]').click();
    cy.get('[data-testid="freeze-indicator-0"]').should('be.visible');

    // Scroll to verify it's frozen
    cy.get('[data-testid="table-scroll-container"]').scrollTo('right');
    cy.get('[data-testid="table-column-id"]').should('be.visible');

    // Scroll back to left
    cy.get('[data-testid="table-scroll-container"]').scrollTo('left');

    // Click unfreeze button
    cy.get('[data-testid="unfreeze-column-btn-0"]').click();

    // Verify freeze indicator is gone
    cy.get('[data-testid="freeze-indicator-0"]').should('not.exist');

    // Scroll horizontally again
    cy.get('[data-testid="table-scroll-container"]').scrollTo('right');

    // Verify first column scrolls out of view (no longer frozen)
    cy.get('[data-testid="table-column-id"]').should('not.be.visible');

    // Scroll back to verify normal behavior restored
    cy.get('[data-testid="table-scroll-container"]').scrollTo('left');
    cy.get('[data-testid="table-column-id"]').should('be.visible');
  });
});

