    cy.get('[data-testid="upload-button"]').should('be.visible');
  });

  it('should handle cancel request failure gracefully', () => {
    // Intercept the upload endpoint
    cy.intercept('POST', '/api/upload', (req) => {
      req.reply((res) => {
        res.delay(3000);
        res.send({ statusCode: 200, body: { success: true } });
      });
    }).as('uploadRequest');

    // Intercept the cancel endpoint to simulate failure
    cy.intercept('POST', '/api/upload/cancel', {
      statusCode: 500,
      body: { error: 'Failed to cancel upload' }
