    // Verify upload continues or gracefully handles the error state
    cy.get('[data-testid="upload-progress"]').should('be.visible');
    cy.get('[data-testid="retry-cancel-button"]').should('be.visible');
  });
});

describe('File Upload Queue - Remove File Before Submit', () => {
