describe('Keyboard Navigation - Tab Key Accessibility', () => {
  beforeEach(() => {
    cy.visit('/form-page');
  });

  it('should navigate through all interactive elements using Tab key in correct order', () => {
    // Start from page load - focus should be manageable
    cy.get('body').click();

    // Tab to first interactive element (Login button)
    cy.get('body').tab();
    cy.get('[data-testid="login-button"]').should('have.focus');

    // Tab to username input field
    cy.get('[data-testid="login-button"]').tab();
    cy.get('[data-testid="username-input"]').should('have.focus');

    // Type in username field while focused
    cy.get('[data-testid="username-input"]').type('testuser@example.com');
    cy.get('[data-testid="username-input"]').should('have.value', 'testuser@example.com');

    // Tab to password input field
    cy.get('[data-testid="username-input"]').tab();
    cy.get('[data-testid="password-input"]').should('have.focus');

    // Type in password field while focused
    cy.get('[data-testid="password-input"]').type('password123');
    cy.get('[data-testid="password-input"]').should('have.value', 'password123');

    // Tab to remember checkbox
    cy.get('[data-testid="password-input"]').tab();
    cy.get('[data-testid="remember-checkbox"]').should('have.focus');

    // Tab to submit button
    cy.get('[data-testid="remember-checkbox"]').tab();
    cy.get('[data-testid="submit-button"]').should('have.focus');
    cy.get('[data-testid="submit-button"]').should('be.visible');

    // Tab to forgot password link
    cy.get('[data-testid="submit-button"]').tab();
    cy.get('[data-testid="forgot-password-link"]').should('have.focus');

    // Verify all elements are interactive and reachable
    cy.get('[data-testid="submit-button"]').should('not.be.disabled');
  });

  it('should skip hidden and disabled elements during Tab navigation', () => {
    cy.get('body').click();

    // Tab to first visible interactive element
    cy.get('body').tab();
    cy.get('[data-testid="login-button"]').should('have.focus');

    // Tab should skip the disabled input field
    cy.get('[data-testid="login-button"]').tab();
    cy.get('[data-testid="username-input"]').should('have.focus');

    // Tab should skip the hidden reset button
    cy.get('[data-testid="username-input"]').tab();
    cy.get('[data-testid="password-input"]').should('have.focus');
    cy.get('[data-testid="hidden-button"]').should('not.be.visible');

    // Verify disabled button is not reachable via Tab
    cy.get('[data-testid="disabled-submit-button"]').should('be.disabled');

    // Tab through remaining elements
    cy.get('[data-testid="password-input"]').tab();
    cy.get('[data-testid="remember-checkbox"]').should('have.focus');

    // Verify focus does not land on disabled element
    cy.get('[data-testid="remember-checkbox"]').tab();
    cy.get('[data-testid="disabled-submit-button"]').should('not.have.focus');

    // Should focus on next enabled element
    cy.get('[data-testid="submit-button"]').should('have.focus');
  });
});

