describe('Dynamic Content Updates Accessibility - Screen Reader Announcements', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
    cy.injectAxe();
  });

  it('should announce dynamic content updates via ARIA live regions to screen readers', () => {
    // Verify live region container exists
    cy.get('[data-testid="live-region"]').should('be.visible');
    cy.get('[data-testid="live-region"]').should('have.attr', 'aria-live', 'polite');
    cy.get('[data-testid="live-region"]').should('have.attr', 'aria-atomic', 'true');

    // Trigger dynamic content update
    cy.get('[data-testid="refresh-data-button"]').click();

    // Intercept API call for data update
    cy.intercept('GET', '/api/content/update').as('contentUpdate');
    cy.wait('@contentUpdate');

    // Verify announcement text appears in live region
    cy.get('[data-testid="live-region"]').should('contain', 'Content has been updated');

    // Verify announcement is hidden from visual display but available to screen readers
    cy.get('[data-testid="live-region"]').should('have.class', 'sr-only');

    // Verify role is properly set for accessibility
    cy.get('[data-testid="live-region"]').should('have.attr', 'role', 'status');

    // Run accessibility checks
    cy.checkA11y('[data-testid="live-region"]', {
      rules: {
        'aria-required-attr': { enabled: true },
        'aria-valid-attr-role': { enabled: true }
      }
    });

    // Verify content in main container is also updated
    cy.get('[data-testid="content-container"]').should('contain', 'Updated');
  });

  it('should handle missing live region and alert when screen reader announcements cannot be made', () => {
    // Remove live region to simulate failure scenario
    cy.get('[data-testid="live-region"]').then(($region) => {
      $region.remove();
    });

    // Attempt to trigger content update
    cy.get('[data-testid="refresh-data-button"]').click();

    // Verify live region no longer exists
    cy.get('[data-testid="live-region"]').should('not.exist');

    // Verify fallback error message is visible for accessibility
    cy.get('[data-testid="accessibility-warning"]').should('be.visible');
    cy.get('[data-testid="accessibility-warning"]').should('contain', 'Screen reader announcement failed');
    cy.get('[data-testid="accessibility-warning"]').should('have.attr', 'role', 'alert');

    // Verify content was still updated despite announcement failure
    cy.get('[data-testid="content-container"]').should('be.visible');

    // Run accessibility violation check
    cy.checkA11y(null, {
      rules: {
        'aria-required-attr': { enabled: true }
      }
    }, (violations) => {
      expect(violations.length).to.be.greaterThan(0);
    });
  });
});

