describe('Reading Order Matches Visual Order - Accessibility', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should maintain correct reading order matching visual layout (happy path)', () => {
    // Intercept API call that loads page content
    cy.intercept('GET', '/api/content').as('loadContent');
    cy.wait('@loadContent');

    // Get all focusable elements in order
    cy.get('[data-testid="main-heading"]').should('be.visible');
    cy.get('[data-testid="main-heading"]').should('contain', 'Welcome');

    // Tab through elements and verify they follow visual order
    cy.get('[data-testid="intro-paragraph"]').should('be.visible');
    cy.get('[data-testid="intro-paragraph"]').should('contain', 'This is the introduction');

    cy.get('[data-testid="primary-button"]').should('be.visible');
    cy.get('[data-testid="primary-button"]').should('contain', 'Get Started');

    cy.get('[data-testid="secondary-button"]').should('be.visible');
    cy.get('[data-testid="secondary-button"]').should('contain', 'Learn More');

    cy.get('[data-testid="footer-content"]').should('be.visible');
    cy.get('[data-testid="footer-content"]').should('contain', 'Footer');

    // Verify DOM order matches visual order by checking tabindex
    cy.get('[data-testid="primary-button"]').should('have.attr', 'tabindex', '0');
    cy.get('[data-testid="secondary-button"]').should('have.attr', 'tabindex', '0');

    // Verify no elements are hidden in DOM but visible to users (negative z-index, etc)
    cy.get('[data-testid="intro-paragraph"]').should('have.css', 'position').and('not.equal', 'absolute');
  });

  it('should identify when reading order does not match visual order (negative case)', () => {
    cy.intercept('GET', '/api/content').as('loadContent');
    cy.wait('@loadContent');

    // Check for common accessibility issues
    cy.get('[data-testid="misaligned-content"]').should('not.exist');

    // Verify no elements with extreme negative margins breaking reading order
    cy.get('body').then(($body) => {
      const elements = $body.find('[data-testid*="button"], [data-testid*="link"]');
      elements.each((index, el) => {
        const marginLeft = Cypress.$(el).css('margin-left');
        const marginTop = Cypress.$(el).css('margin-top');
        expect(marginLeft).not.to.equal('-9999px');
        expect(marginTop).not.to.equal('-9999px');
      });
    });

    // Verify skip links or navigation are not positioned at the end of DOM
    cy.get('[data-testid="skip-link"]').should('exist');
    cy.get('[data-testid="skip-link"]').should('be.visible');

    // Verify hidden decorative elements don't interfere with reading order
    cy.get('[aria-hidden="true"]').each(($el) => {
      cy.wrap($el).should('not.have.attr', 'tabindex');
    });

    // Confirm focus order matches visual order
    cy.get('[data-testid="primary-button"]').click();
    cy.get('[data-testid="primary-button"]').should('have.focus');
  });
});

