describe('Loading States Accessibility - Assistive Technology', () => {
  beforeEach(() => {
    cy.visit('/loading-states');
  });

  it('should communicate loading state to screen readers with aria-busy and aria-label', () => {
    // Setup: Intercept the API call that triggers loading
    cy.intercept('GET', '/api/data/fetch').as('dataFetch');

    // Find and click the button that initiates data loading
    cy.get('[data-testid="load-data-button"]').click();

    // Verify loading state is announced to assistive technology
    cy.get('[data-testid="loading-container"]')
      .should('have.attr', 'aria-busy', 'true')
      .should('have.attr', 'aria-label')
      .and('contain', 'Loading');

    // Verify spinner element has proper ARIA attributes
    cy.get('[data-testid="spinner"]')
      .should('have.attr', 'role', 'status')
      .should('have.attr', 'aria-live', 'polite')
      .should('contain', 'Loading in progress');

    // Wait for API response
    cy.wait('@dataFetch');

    // Verify loading state is removed after completion
    cy.get('[data-testid="loading-container"]')
      .should('have.attr', 'aria-busy', 'false');

    // Verify completion message is announced
    cy.get('[data-testid="status-message"]')
      .should('have.attr', 'aria-live', 'assertive')
      .should('contain', 'Data loaded successfully');

    // Verify content is now visible
    cy.get('[data-testid="loaded-content"]').should('be.visible');
  });

