describe('Prefers Reduced Motion Accessibility Feature', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should respect prefers-reduced-motion when enabled and disable animations', () => {
    // Set the prefers-reduced-motion media query to 'reduce'
    cy.visit('/', {
      onBeforeLoad(win) {
        cy.stub(win, 'matchMedia')
          .withArgs('(prefers-reduced-motion: reduce)')
          .returns({
            matches: true,
            media: '(prefers-reduced-motion: reduce)',
            onchange: null,
            addListener: cy.stub(),
            removeListener: cy.stub(),
            addEventListener: cy.stub(),
            removeEventListener: cy.stub(),
            dispatchEvent: cy.stub(),
          });
      },
    });

    // Verify that the animated button element does not have animation classes
    cy.get('[data-testid="animated-button"]')
      .should('be.visible')
      .should('have.class', 'no-animation');

    // Verify that transitions are disabled in computed style
    cy.get('[data-testid="animated-button"]').then(($el) => {
      const computedStyle = window.getComputedStyle($el[0]);
      expect(computedStyle.transitionDuration).to.equal('0s');
    });

    // Interact with the animated button and verify no animation occurs
    cy.get('[data-testid="animated-button"]').click();
    cy.get('[data-testid="animation-feedback"]')
      .should('be.visible')
      .should('contain', 'Action completed');
  });

  it('should allow animations when prefers-reduced-motion is not set', () => {
    // Set the prefers-reduced-motion media query to 'no-preference'
    cy.visit('/', {
      onBeforeLoad(win) {
        cy.stub(win, 'matchMedia')
          .withArgs('(prefers-reduced-motion: reduce)')
          .returns({
            matches: false,
            media: '(prefers-reduced-motion: reduce)',
            onchange: null,
            addListener: cy.stub(),
            removeListener: cy.stub(),
            addEventListener: cy.stub(),
            removeEventListener: cy.stub(),
            dispatchEvent: cy.stub(),
          });
      },
    });

    // Verify that the animated button has animation classes
    cy.get('[data-testid="animated-button"]')
      .should('be.visible')
      .should('not.have.class', 'no-animation');

    // Verify that transitions are enabled in computed style
    cy.get('[data-testid="animated-button"]').then(($el) => {
      const computedStyle = window.getComputedStyle($el[0]);
      expect(computedStyle.transitionDuration).to.not.equal('0s');
    });

    // Click and verify smooth animation occurs
    cy.get('[data-testid="animated-button"]').click();
    cy.get('[data-testid="animation-feedback"]')
      .should('be.visible')
      .should('contain', 'Animated action completed');
  });
});

