    cy.viewport('iphone-x');
    cy.reload();

    // Verify sticky behavior returns on mobile
    cy.get('[data-testid="footer-nav"]').should('have.css', 'position', 'fixed');

    // Test edge case: verify footer nav does not hide critical content
    cy.get('[data-testid="main-content"]').then(($content) => {
      const contentHeight = $content.height();
      cy.get('[data-testid="footer-nav"]').then(($footer) => {
        const footerHeight = $footer.height();
        cy.get('body').should('have.css', 'padding-bottom').and('not.equal', '0px');
