describe('Product Image Pinch-to-Zoom Functionality', () => {
  beforeEach(() => {
    cy.visit('/product/12345');
  });

  it('should zoom in on product image with pinch gesture', () => {
    // Verify product image is visible
    cy.get('[data-testid="product-image"]')
      .should('be.visible')
      .should('have.css', 'transform', 'matrix(1, 0, 0, 1, 0, 0)');

    // Simulate pinch-to-zoom gesture on the image
    cy.get('[data-testid="product-image"]').trigger('touchstart', {
      touches: [
        { clientX: 100, clientY: 100 },
        { clientX: 200, clientY: 200 }
      ],
      targetTouches: [
        { clientX: 100, clientY: 100 },
        { clientX: 200, clientY: 200 }
      ]
    });

    cy.get('[data-testid="product-image"]').trigger('touchmove', {
      touches: [
        { clientX: 80, clientY: 80 },
        { clientX: 220, clientY: 220 }
      ],
      targetTouches: [
        { clientX: 80, clientY: 80 },
        { clientX: 220, clientY: 220 }
      ]
    });

    cy.get('[data-testid="product-image"]').trigger('touchend', {
      touches: [],
      targetTouches: []
    });

    // Verify zoom was applied (transform matrix should change)
    cy.get('[data-testid="product-image"]')
      .should('be.visible')
      .invoke('css', 'transform')
      .should('not.equal', 'matrix(1, 0, 0, 1, 0, 0)');

    // Verify zoom controls are displayed
    cy.get('[data-testid="zoom-reset-button"]').should('be.visible');
  });

  it('should not zoom beyond maximum scale and handle edge case gracefully', () => {
    // Verify initial state
    cy.get('[data-testid="product-image"]').should('be.visible');

    // Attempt multiple consecutive pinch gestures to exceed max zoom
    for (let i = 0; i < 5; i++) {
      cy.get('[data-testid="product-image"]').trigger('touchstart', {
        touches: [
          { clientX: 100, clientY: 100 },
          { clientX: 150, clientY: 150 }
        ],
        targetTouches: [
          { clientX: 100, clientY: 100 },
          { clientX: 150, clientY: 150 }
        ]
      });

      cy.get('[data-testid="product-image"]').trigger('touchmove', {
        touches: [
          { clientX: 50, clientY: 50 },
          { clientX: 250, clientY: 250 }
        ],
        targetTouches: [
          { clientX: 50, clientY: 50 },
          { clientX: 250, clientY: 250 }
        ]
      });

      cy.get('[data-testid="product-image"]').trigger('touchend', {
        touches: [],
        targetTouches: []
      });
    }

    // Verify image is still visible and hasn't broken
    cy.get('[data-testid="product-image"]').should('be.visible');

    // Verify zoom level is capped at maximum
    cy.get('[data-testid="zoom-level-display"]')
      .should('contain', '500%')
      .or('contain', '400%');

    // Reset button should be available and functional
    cy.get('[data-testid="zoom-reset-button"]').click();
    cy.get('[data-testid="product-image"]')
      .invoke('css', 'transform')
      .should('equal', 'matrix(1, 0, 0, 1, 0, 0)');
  });
});

