});

describe('Video Player Responsive Resize on Tablet Viewports', () => {
  beforeEach(() => {
    cy.visit('/video-player');
  });

  it('should resize video player proportionally when viewport changes to tablet size', () => {
    // Set initial desktop viewport
    cy.viewport(1920, 1080);

    // Verify video player is visible on desktop
    cy.get('[data-testid="video-player"]').should('be.visible');
    cy.get('[data-testid="video-player"]').then(($player) => {
      const desktopWidth = $player.width();
      const desktopHeight = $player.height();
      expect(desktopWidth).to.be.greaterThan(0);
      expect(desktopHeight).to.be.greaterThan(0);
    });

    // Resize to tablet viewport
    cy.viewport('ipad-2');

    // Verify video player still visible and resized
    cy.get('[data-testid="video-player"]').should('be.visible');
    cy.get('[data-testid="video-player"]').then(($player) => {
      const tabletWidth = $player.width();
      const tabletHeight = $player.height();
      expect(tabletWidth).to.be.lessThan(1920);
      expect(tabletHeight).to.be.lessThan(1080);
    });

    // Verify aspect ratio is maintained (within tolerance)
    cy.get('[data-testid="video-player"]').then(($player) => {
      const width = $player.width();
      const height = $player.height();
      const aspectRatio = width / height;
      expect(aspectRatio).to.be.closeTo(16 / 9, 0.1);
    });

    // Verify play button is still accessible
    cy.get('[data-testid="play-button"]').should('be.visible').click();
    cy.get('[data-testid="video-player"] video').should('have.prop', 'paused', false);
  });

  it('should handle edge case of very small tablet viewport without breaking layout', () => {
    // Set very small tablet viewport
    cy.viewport(480, 600);

    // Verify video player is visible
    cy.get('[data-testid="video-player"]').should('be.visible');

    // Verify player does not overflow container
    cy.get('[data-testid="video-container"]').then(($container) => {
      const containerWidth = $container.width();
      cy.get('[data-testid="video-player"]').then(($player) => {
        const playerWidth = $player.width();
        expect(playerWidth).to.be.lessThanOrEqual(containerWidth);
      });
    });

    // Verify controls are still visible and not hidden
    cy.get('[data-testid="player-controls"]').should('be.visible');
    cy.get('[data-testid="volume-button"]').should('be.visible');
    cy.get('[data-testid="fullscreen-button"]').should('be.visible');

    // Verify minimum dimensions are respected
    cy.get('[data-testid="video-player"]').then(($player) => {
      const width = $player.width();
      const height = $player.height();
      expect(width).to.be.greaterThanOrEqual(280);
      expect(height).to.be.greaterThanOrEqual(157);
    });
  });
});

