describe('Expired Promo Code Error Handling', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should display error message when applying an expired promo code', () => {
    // Arrange: Set up API intercept for promo code validation
    cy.intercept('POST', '/api/promo-codes/validate').as('validatePromo');

    // Act: Fill in promo code field
    cy.get('[data-testid="promo-code-input"]').should('be.visible').type('EXPIRED2023');

    // Act: Click apply button
    cy.get('[data-testid="apply-promo-btn"]').should('be.visible').click();

    // Assert: Wait for API call and verify error response
    cy.wait('@validatePromo').then((interception) => {
      expect(interception.response.statusCode).to.equal(400);
    });

    // Assert: Verify error message is displayed
    cy.get('[data-testid="promo-error-message"]')
      .should('be.visible')
      .should('contain', 'This promo code has expired');

    // Assert: Verify error styling is applied
    cy.get('[data-testid="promo-code-input"]').should('have.class', 'error-state');

    // Assert: Verify discount is not applied
    cy.get('[data-testid="discount-amount"]').should('contain', '$0.00');
  });

  it('should clear error message when user enters a valid promo code after invalid attempt', () => {
    // Arrange: Set up API intercepts for both invalid and valid responses
    cy.intercept('POST', '/api/promo-codes/validate', { statusCode: 400, body: { error: 'Expired' } }).as('invalidPromo');

    // Act: First attempt with expired code
    cy.get('[data-testid="promo-code-input"]').should('be.visible').type('EXPIRED2023');
    cy.get('[data-testid="apply-promo-btn"]').should('be.visible').click();
    cy.wait('@invalidPromo');

    // Assert: Error message is visible
    cy.get('[data-testid="promo-error-message"]').should('be.visible');

    // Arrange: Update intercept for valid code
    cy.intercept('POST', '/api/promo-codes/validate', { statusCode: 200, body: { discount: 15, code: 'VALID2024' } }).as('validPromo');

    // Act: Clear field and enter valid code
    cy.get('[data-testid="promo-code-input"]').should('be.visible').clear().type('VALID2024');
    cy.get('[data-testid="apply-promo-btn"]').should('be.visible').click();
    cy.wait('@validPromo');

    // Assert: Error message should not exist
    cy.get('[data-testid="promo-error-message"]').should('not.exist');

    // Assert: Success message should be visible
    cy.get('[data-testid="promo-success-message"]')
      .should('be.visible')
      .should('contain', 'Promo code applied successfully');

    // Assert: Discount should be applied
    cy.get('[data-testid="discount-amount"]').should('contain', '$15.00');
  });
});

