describe('Payment Loading State', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should display loading state while payment is processing', () => {
    cy.get('[data-testid="card-number-input"]').type('4111111111111111');
    cy.get('[data-testid="card-expiry-input"]').type('12/25');
    cy.get('[data-testid="card-cvc-input"]').type('123');
    cy.get('[data-testid="cardholder-name-input"]').type('John Doe');

    cy.intercept('POST', '/api/payments/process').as('processPayment');

    cy.get('[data-testid="submit-payment-btn"]').click();

    cy.get('[data-testid="payment-loading-spinner"]').should('be.visible');
    cy.get('[data-testid="loading-text"]').should('contain', 'Processing your payment');
    cy.get('[data-testid="submit-payment-btn"]').should('be.disabled');

    cy.wait('@processPayment');

    cy.get('[data-testid="payment-loading-spinner"]').should('not.exist');
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Payment successful');
    cy.get('[data-testid="order-confirmation"]').should('be.visible');
  });

  it('should handle payment processing timeout and display error state', () => {
    cy.get('[data-testid="card-number-input"]').type('5555555555554444');
    cy.get('[data-testid="card-expiry-input"]').type('06/26');
    cy.get('[data-testid="card-cvc-input"]').type('456');
    cy.get('[data-testid="cardholder-name-input"]').type('Jane Smith');

    cy.intercept('POST', '/api/payments/process', (req) => {
      req.destroy();
    }).as('processPaymentTimeout');

    cy.get('[data-testid="submit-payment-btn"]').click();

    cy.get('[data-testid="payment-loading-spinner"]').should('be.visible');
    cy.get('[data-testid="loading-text"]').should('contain', 'Processing your payment');

    cy.wait('@processPaymentTimeout', { requestTimeout: 10000 }).catch(() => {
      cy.get('[data-testid="payment-loading-spinner"]').should('not.exist');
      cy.get('[data-testid="error-message"]').should('be.visible');
      cy.get('[data-testid="error-message"]').should('contain', 'Payment processing failed');
      cy.get('[data-testid="submit-payment-btn"]').should('not.be.disabled');
      cy.get('[data-testid="retry-btn"]').should('be.visible');
    });
  });
});

