describe('Notification Auto-Dismiss Feature', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should auto-dismiss notification after 5 seconds', () => {
    cy.get('[data-testid="trigger-notification-btn"]').click();
    cy.get('[data-testid="notification-toast"]').should('be.visible');
    cy.get('[data-testid="notification-toast"]').should('contain', 'Success');

    // Verify notification is still visible before 5 seconds
    cy.wait(2000);
    cy.get('[data-testid="notification-toast"]').should('be.visible');

    // Wait for auto-dismiss and verify it's gone after 5 seconds
    cy.wait(3500);
    cy.get('[data-testid="notification-toast"]').should('not.exist');
  });

  it('should not auto-dismiss when user hovers over notification', () => {
    cy.get('[data-testid="trigger-notification-btn"]').click();
    cy.get('[data-testid="notification-toast"]').should('be.visible');

    // Hover over notification to pause auto-dismiss
    cy.get('[data-testid="notification-toast"]').trigger('mouseenter');
    cy.wait(5500);

    // Notification should still be visible after 5+ seconds due to hover
    cy.get('[data-testid="notification-toast"]').should('be.visible');

    // Move mouse away and wait for dismissal
    cy.get('[data-testid="notification-toast"]').trigger('mouseleave');
    cy.wait(5500);
    cy.get('[data-testid="notification-toast"]').should('not.exist');
  });
});

